def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    reqs = [WATER_REQ]
    bob_prev_bid = None
    max_prev_bid = 0.0
    urgent_opp = 0
    rich_opp = 0

    for oid, opp in alive:
        reqs.append(float(opp.get('water_requirement', WATER_REQ)))
        if opp.get('budget', 0) >= DAILY_SALARY:
            rich_opp += 1
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            urgent_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            pbid = float(pbid)
            if pbid > max_prev_bid:
                max_prev_bid = pbid
            if oid == 'Bob':
                bob_prev_bid = pbid

    total_req = sum(reqs)
    scarcity = total_req / max(supply, 1.0)
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)

    risk = 0.0
    if hp <= 2:
        risk += 0.9
    elif hp <= 4:
        risk += 0.45
    if no_water >= 2:
        risk += 1.0
    elif no_water >= 1:
        risk += 0.45
    if scarcity > 2.2:
        risk += 0.55
    elif scarcity > 1.8:
        risk += 0.3
    if urgent_opp >= 1:
        risk += 0.15
    if rich_opp >= 1:
        risk += 0.1

    base_frac = 0.28 + (1.0 - supply_ratio) * 0.22
    if day >= 8:
        base_frac += 0.08
    if risk >= 1.4:
        base_frac = max(base_frac, 0.92)
    elif risk >= 0.9:
        base_frac = max(base_frac, 0.72)
    elif risk >= 0.45:
        base_frac = max(base_frac, 0.54)

    target = DAILY_SALARY * base_frac

    if bob_prev_bid is not None:
        if risk >= 0.9 or supply <= 17:
            target = max(target, bob_prev_bid + 2.5)
        elif bob_prev_bid >= DAILY_SALARY * 0.95 and hp > 4 and no_water == 0 and supply >= 20:
            target = min(target, DAILY_SALARY * 0.32)
        elif bob_prev_bid <= DAILY_SALARY * 0.55 and (supply <= 18 or risk >= 0.45):
            target = max(target, bob_prev_bid + 1.5)
    elif max_prev_bid > 0 and (risk >= 0.45 or supply <= 18):
        target = max(target, max_prev_bid + 1.5)

    if budget < DAILY_SALARY * 0.6 and hp > 4 and no_water == 0 and supply >= 20:
        target = min(target, budget * 0.55)

    if hp <= 2 or no_water >= 2:
        target = max(target, DAILY_SALARY * 0.95)

    bid = min(float(budget), float(target))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    prev_bids = []
    prev_hp_after = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
                prev_hp_after.append(float(prev.get('hp_after', 0.0)))
            except Exception:
                pass

    # If we have no bid info, default to a conservative mid bid
    if not prev_bids:
        base = DAILY_SALARY * 0.55
    else:
        highest_prev_bid = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

        # If someone was willing to overpay (Alex-like), we don't match blindly.
        # We instead aim to slightly exceed the second-highest pressure.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            base = max(second_prev + 1.5, DAILY_SALARY * 0.45)
        else:
            base = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.5)

    # Scale by supply: higher supply reduces need to overbid
    # Expected water share depends on supply; we approximate urgency by how many WATER_REQ units exist.
    units = supply / float(WATER_REQ)
    if units <= 1.2:
        supply_factor = 1.15
    elif units <= 1.8:
        supply_factor = 1.05
    else:
        supply_factor = 0.95

    # Urgency by our HP and streak without water
    if hp <= 2 or no_water_days >= 2:
        urgency_factor = 1.25
    elif hp <= 4:
        urgency_factor = 1.10
    else:
        urgency_factor = 0.95

    # Keep bid within budget and a reasonable fraction of daily salary
    target = base * supply_factor * urgency_factor
    cap = DAILY_SALARY * 0.75

    bid = max(0.0, min(budget, min(target, cap)))

    # If budget is tiny, bid whatever we can
    if budget <= 1.0:
        return max(0.0, budget)

    return float(bid)
